class BoostingStrategy:
    """ISOTROPIC Boosting: Newton Optimized Ensemble with Geometric Targets.

    Innovation 1: Empirical Bayes targets - prob - y for classification
      and y - current_preds for regression (squared error gradient).
    Innovation 2: Margin-focused weights - |margin| + alpha * fitted.
    Innovation 3: Adaptive alpha - Gauss-Newton step, not fixed unity.

    Key insight: Data-driven target computation + margin reweighting beats
    uniform or exponential reweighting in boosting optimization.
    """

    def __init__(self, config):
        self.config = config
        self.task_type = config["task_type"]
        self.n_rounds = config["n_rounds"]
        self.learning_rate = config["learning_rate"]
        self.lmbd = 0.01

    def init_weights(self, n_samples):
        return np.ones(n_samples) / n_samples

    def _sigmoid(self, x):
        return 1.0 / (1.0 + np.exp(-np.clip(x, -500, 500)))

    def compute_targets(self, y, current_predictions, sample_weights, round_idx):
        if self.task_type == "classification":
            prob = self._sigmoid(current_predictions)
            return prob - y
        else:
            return y - current_predictions

    def compute_learner_weight(self, learner, X, y, pseudo_targets,
                                sample_weights, round_idx):
        preds = learner.predict(X)
        if self.task_type == "classification":
            alpha = np.sum(pseudo_targets * preds) / (np.sum(preds ** 2) + self.lmbd)
        else:
            alpha = np.sum(pseudo_targets * preds) / (np.sum(preds ** 2) + self.lmbd)
        return np.clip(alpha, 0.0, 2.0)

    def update_weights(self, sample_weights, learner, X, y, pseudo_targets,
                       alpha, round_idx):
        preds = learner.predict(X)
        if self.task_type == "classification":
            binary = preds.astype(int)
            margin = np.abs(binary - y)
            new_weights = sample_weights * (margin + 2 * alpha)
        else:
            margin = np.abs(preds - pseudo_targets)
            new_weights = sample_weights * (margin + alpha * pseudo_targets)
        return new_weights / new_weights.sum()

